import{_ as i,o as a,c as t,ah as e}from"./chunks/framework.B3SnS1TC.js";const c=JSON.parse('{"title":"Hyper-V 直通 T4 空闲高温：配置 NVIDIA 持久化服务","description":"Hyper-V 直通 T4 空闲高温：配置 NVIDIA 持久化服务","frontmatter":{"date":"2022-12-18T00:00:00.000Z","title":"Hyper-V 直通 T4 空闲高温：配置 NVIDIA 持久化服务","category":"linux","tags":["linxu","gpu"],"description":"Hyper-V 直通 T4 空闲高温：配置 NVIDIA 持久化服务"},"headers":[],"relativePath":"posts/nvidia_gpu_temperature_anomaly.md","filePath":"posts/nvidia_gpu_temperature_anomaly.md"}'),n={name:"posts/nvidia_gpu_temperature_anomaly.md"};function p(d,s,h,l,r,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="hyper-v-直通-t4-空闲高温-配置-nvidia-持久化服务" tabindex="-1">Hyper-V 直通 T4 空闲高温：配置 NVIDIA 持久化服务 <a class="header-anchor" href="#hyper-v-直通-t4-空闲高温-配置-nvidia-持久化服务" aria-label="Permalink to &quot;Hyper-V 直通 T4 空闲高温：配置 NVIDIA 持久化服务&quot;">​</a></h1><p>环境：Hyper-V 直通 Tesla T4，Debian 13，NVIDIA 驱动 <code>575.57.08</code>。</p><h2 id="现象与判断" tabindex="-1">现象与判断 <a class="header-anchor" href="#现象与判断" aria-label="Permalink to &quot;现象与判断&quot;">​</a></h2><p>长时间未连接 SSH 后，首次运行 <code>nvidia-smi</code>，GPU 温度竟然达到 94℃。当时没有列出 GPU 业务进程，显存占用为 0 MiB，但显卡处于 P0，功耗约 40W。</p><p>随后几分钟温度逐渐下降，现场读数如下：</p><table tabindex="0"><thead><tr><th>阶段</th><th>持久化</th><th>状态</th><th>温度</th><th>功耗</th></tr></thead><tbody><tr><td>首次查询</td><td>Off</td><td>P0</td><td>94℃</td><td>40W</td></tr><tr><td>约两分钟后</td><td>Off</td><td>P0</td><td>71℃</td><td>33W</td></tr><tr><td>手动开启持久化数分钟后</td><td>On</td><td>P8</td><td>43℃</td><td>14W</td></tr><tr><td>安装服务后检查</td><td>On</td><td>P8</td><td>36℃</td><td>约 10W</td></tr></tbody></table><p>P0 是最高性能档位，不代表满负载；P8 是本例中的低功耗档位。</p><p>检查发现，驱动已经加载，<code>nvidia-persistenced</code> 程序也已安装，但缺少开机服务。<strong>降温在开启持久化前就已开始，因此尚不能断定整个现象都由缺少持久化导致。</strong></p><h2 id="解决办法-让持久化服务随系统启动" tabindex="-1">解决办法：让持久化服务随系统启动 <a class="header-anchor" href="#解决办法-让持久化服务随系统启动" aria-label="Permalink to &quot;解决办法：让持久化服务随系统启动&quot;">​</a></h2><p>没有 GPU 客户端且未开启持久化时，驱动可能释放设备状态。<code>nvidia-persistenced</code> 通过持续持有设备文件维持初始化状态，无须运行计算任务来“保活”。<a href="https://docs.nvidia.com/deploy/driver-persistence/persistence-daemon.html" target="_blank" rel="noreferrer">NVIDIA 官方持久化说明</a></p><p>手动执行 <code>sudo nvidia-smi -pm 1</code> 可以立即开启持久化，但不会跨重启保存，所以还需要配置开机服务。<a href="https://docs.nvidia.com/deploy/nvidia-smi/index.html" target="_blank" rel="noreferrer">NVIDIA nvidia-smi 文档</a></p><p>下面的脚本使用<strong>已安装驱动自带的示例包</strong>，适用于程序和示例包均存在、但尚未安装服务的机器。不同发行版路径可能不同；已有服务时，优先检查并启用现有配置。</p><p>在 root 终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  nvpd_tmp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mktemp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/nvpd-init.XXXXXX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xjf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    /usr/share/doc/NVIDIA_GLX-1.0/samples/nvidia-persistenced-init.tar.bz2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$nvpd_tmp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$nvpd_tmp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/nvidia-persistenced-init&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>脚本会创建专用系统账号、安装 systemd 服务、设置开机启动并立即运行，无须重装驱动或重启系统。专用账号禁止登录，日常通过 systemd 管理即可。</p><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-enabled</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia-persistenced</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia-persistenced</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvidia-smi</span></span></code></pre></div><p>应看到服务为 <code>enabled</code>、<code>active (running)</code>，GPU 的 <code>Persistence-M</code> 为 <code>On</code>。</p><p>另有一台双 T4 物理机，长期运行着 Python GPU 程序。安装后持久化成功开启，但仍为 P0、每张约 31W：<strong>持久化服务不会强制进入 P8，也不会清空业务显存。</strong></p><p>截至记录时，服务已验证生效，重启后的长期效果仍待观察。计划重启后先无人登录空闲 10–20 分钟，再检查首次温度读数和本次启动日志：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia-persistenced</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><p>如果持久化正常后仍持续高温，还需要检查负载、风扇和风道，不能把持久化当成通用降温开关。</p>`,22)])])}const F=i(n,[["render",p]]);export{c as __pageData,F as default};
